const b = $input.first().json.body || $input.first().json || {};
const op = (b.op || 'get').toString();
if (!['get', 'set'].includes(op)) throw new Error('unknown op');
const ALLOW = { 'llm.qa': ['gemini', 'qwen3:4b'], 'tts.engine': ['auto', 'neural', 'piper'], 'ocr.engine': ['gemini', 'easyocr'] };
let sql = '';
let key = '';
let v = '';
let setkey = false;
if (op === 'get') {
  sql = `SELECT key, value FROM app_settings WHERE key IN ('llm.qa', 'tts.engine', 'ocr.engine', 'voice.llm_model', 'gemini.api_key')`;
} else {
  key = (b.key || '').toString();
  v = (b.value || '').toString();
  if (!key && b.model !== undefined) { key = 'llm.qa'; v = b.model.toString(); }
  if (key === 'n8n.api_key') throw new Error('forbidden');
  if (key === 'gemini.api_key') {
    if (!/^[A-Za-z0-9._-]{20,500}$/.test(v)) throw new Error('รูปแบบ API key ไม่ถูกต้อง (20-500 ตัวอักษร: A-Z a-z 0-9 . _ -)');
    setkey = true;
  } else {
    if (!ALLOW[key]) throw new Error('unknown key');
    if (!ALLOW[key].includes(v)) throw new Error('unknown value');
  }
  const q = (s) => s.replace(/'/g, "''");
  sql = `INSERT INTO app_settings (key, value, updated_at) VALUES ('${key}', '${q(v)}', NOW()) ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value, updated_at = NOW() RETURNING value`;
}
return [{ json: { op: op, key: key, v: v, setkey: setkey, sql: sql } }];

const it = $input.first().json;
const t = $('Build SQL').first().json;
const ok = !(it && it.error);
const raw = (t.v || '').toString();
const mask = raw.length >= 8 ? (raw.slice(0, 4) + '••••••' + raw.slice(-3)) : '';
if (!ok) {
  const em = ((it.error && (it.error.message || it.error.description)) || it.error || 'unknown').toString().slice(0, 300);
  return [{ json: { ok: false, key: 'gemini.api_key', value: mask, credential_updated: false, error: 'บันทึก key แล้ว แต่หมุน credential ไม่สำเร็จ: ' + em + ' — กดบันทึกซ้ำได้' } }];
}
return [{ json: { ok: true, key: 'gemini.api_key', value: mask, credential_updated: true } }];

const t = $('Build SQL').first().json;
const ALLOW = { 'llm.qa': ['gemini', 'qwen3:4b'], 'tts.engine': ['auto', 'neural', 'piper'], 'ocr.engine': ['gemini', 'easyocr'] };
const rows = $input.all().map(r => r.json);
if (t.op === 'set') {
  const v = rows.length && rows[0].value !== undefined ? rows[0].value : '';
  return [{ json: { ok: true, key: t.key, value: v } }];
}
const m = {};
rows.forEach(r => { m[r.key] = r.value; });
let qa = m['llm.qa'] || m['voice.llm_model'] || 'gemini';
if (!ALLOW['llm.qa'].includes(qa)) qa = 'gemini';
let te = m['tts.engine'] || 'auto';
if (!ALLOW['tts.engine'].includes(te)) te = 'auto';
let oe = m['ocr.engine'] || 'gemini';
if (!ALLOW['ocr.engine'].includes(oe)) oe = 'gemini';
let gk = (m['gemini.api_key'] || '').toString();
let gmask = gk.length >= 8 ? (gk.slice(0, 4) + '••••••' + gk.slice(-3)) : '';
return [{ json: { ok: true, settings: { 'llm.qa': qa, 'tts.engine': te, 'ocr.engine': oe, 'gemini.api_key_masked': gmask }, model: qa, models: ['gemini', 'qwen3:4b'] } }];
